 roster.records.forEach((r,index)=>{if(r.semantics?.kind==='collection_all')for(const id of r.semantics.collection_indices)add(id,{kind:'compound_possession',flag:r.flag_id,source:`web/assets/data/roster_predicate_table.json#/records/${index}/semantics`,convertedOp:`collection_all(${r.semantics.collection_indices.join(',')})`,consumer:'web/flag-store.js / engine/dw3/dw3-config.ts'});});
 const boosters=read('web/assets/data/card_boosters.json');
 for(const set of boosters.sets) add(set.setId,{kind:'booster_open',source:'web/assets/data/card_boosters.json',record:set.record,pools:set.pools.map(p=>p.address),consumer:'engine/systems/card-battle.ts openPack → engine/dw3/booster-stock.ts',original:'/home/dorij/ddw3/asm/dw2003/pro/stcrdshp.s:2069',stockRead:'/home/dorij/ddw3/asm/dw2003/pro/stcrdshp.s:2129',cards:6});
 const opponents=read('web/assets/data/card_opponents.json');
 for(const o of opponents.opponents) if(o.packSetId) add(o.packSetId,{kind:'duel_booster_reward',opponent:o.id,source:'web/assets/data/card_opponents.json',consumer:'web/cardstate.js grantPackForOpponent / web/cardduel-native.js commit',original:'/home/dorij/ddw3/asm/dw2003/pro/cardgame.s:33088'});
