 for(const group of [cardmon.odd,cardmon.even,{default:cardmon.default}])for(const choice of Object.values(group))for(const pair of [choice,choice.story2d])if(pair)for(const id of [pair.nz,pair.z])cardmonIds.add(id);
 for(const id of [...cardmonIds].sort((a,b)=>a-b))add(id,{kind:'cardmon_booster_reward',source:'web/assets/data/cardmon_boosters.json',consumer:'engine/dw3/cardmon-booster.ts → web/battle.js result → shared item bag',evidence:'docs/research/field/fishing-system-decoded-2026-07-11.md:219'});
